const products=[
{id:'keynade-mx',name:'Keynade MX',en:'12-KEY MECHANICAL FIDGET',type:'press',format:'列印成品',color:'#eee8de',art:'photo',image:'keynade/01-front.jpg',price:499,verified:true,desc:'12 個獨立機械按鍵，把鍵盤的手感握進掌心。',detail:'手雷造型與機械鍵軸結合的掌心紓壓小物。12 個大面板可獨立按壓，其餘小面板為固定造型件。轉動握持角度，找到下一個想按的位置。',mark:'01'},
{id:'cloud-key',name:'按鍵吊飾',en:'TAKE JOY WITH YOU',type:'press',format:'列印成品',color:'#f6dfab',art:'cloud',desc:'把一朵軟乎乎的好心情，掛在身邊。',detail:'將按鍵玩法帶在身邊的吊飾類別。具體商品照片、規格與配件以正式發布為準。',mark:'02'},
{id:'spin-ring',name:'旋轉紓壓小物',en:'ROUND & ROUND',type:'spin',format:'列印成品',color:'#f1c6b5',art:'spin',desc:'手指轉一圈，日常多一點輕鬆。',detail:'以手指旋轉玩法為主的紓壓小物類別。具體造型、結構與配件以正式發布為準。',mark:'03'},
{id:'good-file',name:'數位設計檔案',en:'MAKE YOUR OWN GOOD',type:'file',format:'數位檔案',color:'#cfdfcd',art:'file',desc:'用自己的列印機，讓一個好點子成形。',detail:'提供給希望自行列印和組裝的使用者。商品照片、檔案格式、配件及授權範圍以正式發布為準。',mark:'04'}];
function assetUrl(path){return (/\/(en|zh-cn)\//.test(location.pathname)?'../assets/':'assets/')+path;}
function priceLabel(p){return p.price?'NT$'+p.price:'NT$ · 售價未公布';}
function art(p){if(p.image)return `<img class="real-product-image" src="${assetUrl(p.image)}" alt="Keynade MX 金色成品正面實拍" loading="lazy" decoding="async">`;if(p.type==='file')return `<span class="photo-slot"><span class="slot-type">數位商品</span><strong>數位設計</strong><small>自行列印 · 不含實體商品</small></span>`;return `<span class="photo-slot" aria-hidden="true"></span>`}

const qs=s=>document.querySelector(s);
const makerWorldProfile='https://makerworld.com/zh/@OGStudio';
// Set verified live product URLs here once the store is open.
const saleLinks={};
let filter='all';
function buyAction(p){const url=saleLinks[p.id];if(url&&/^https:\/\/myship\.7-11\.com\.tw\//.test(url))return `<a class="button yellow" href="${url}" target="_blank" rel="noopener noreferrer">前往 7-ELEVEN 賣貨便購買</a>`;return '<span class="sale-status">尚未開賣</span>';}
function renderProducts(){if(!qs('#products'))return;qs('#products').innerHTML=products.filter(p=>document.body.dataset.catalog==='digital'?p.type==='file':p.type!=='file'&&(filter==='all'||p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="查看${p.name}詳情">${art(p)}${p.type==='file'?`<span class="card-stamp">${p.format}</span>`:''}<span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>${p.verified?'12 KEYS':'商品類別'}</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>${priceLabel(p)}</span><button class="text-button card-details" data-detail="${p.id}">查看詳情</button></div></div></article>`).join('');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts();}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return;if(p.type!=='file'){location.href='product.html?id='+encodeURIComponent(id);return;}qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">數位商品 · 不含實體商品</span><p class="detail-note">設計檔案尚未開賣，檔案內容與授權以正式發布為準。</p><a class="button mint" href="${makerWorldProfile}" target="_blank" rel="noopener noreferrer">我們的 MakerWorld 設計主頁</a></div></div>`;qs('#product-dialog').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.detail)detail(b.dataset.detail);if(b.hasAttribute('data-close'))b.closest('dialog').close();});
qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
qs('#year').textContent=new Date().getFullYear();renderProducts();
const profileSlot=qs('#makerworld-profile');if(profileSlot){const link=document.createElement('a');link.className='button mint';link.href=makerWorldProfile;link.target='_blank';link.rel='noopener noreferrer';link.textContent='我們的 MakerWorld 設計主頁';profileSlot.append(link);profileSlot.hidden=false;}
const pageLinks={home:'index.html',products:'products.html',designs:'design-files.html',about:'about.html',product:'products.html'};document.querySelectorAll('header nav:not(.language-switch) a,.catalog-nav a').forEach(a=>{if(a.getAttribute('href')===pageLinks[document.body.dataset.page])a.setAttribute('aria-current','page');});
const keynadePhotos=[{file:'keynade/01-front.jpg',label:'正面實拍'},{file:'keynade/02-side.jpg',label:'側面實拍'},{file:'keynade/03-top-and-pin.jpg',label:'頂部與裝飾插銷實拍'}];
if(qs('#full-product')){const id=new URLSearchParams(location.search).get('id');const p=products.find(p=>p.id===(id==='good-key'?'keynade-mx':id)&&p.type!=='file');if(!p){qs('#full-product').innerHTML='<h1>找不到這件商品。</h1><p>請返回實體商品頁，重新選擇。</p><a class="button yellow" href="products.html">瀏覽實體商品</a>';}else if(p.id==='keynade-mx'){renderKeynade(p);}else{document.title=p.name+' — One Goods Studio';qs('#full-product').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en} / ${p.type==='press'?'按壓派':'旋轉派'}</span><h1>${p.name}</h1><span class="pill">實體商品</span><p>${p.detail}</p><p><strong>NT$ · 售價未公布</strong></p>${buyAction(p)}<div class="product-purchase-note"><b>購買管道：7-ELEVEN 賣貨便</b><p class="detail-note">商品照片、材質、尺寸及售價以正式發布為準。目前尚未開賣。</p></div></div></div>`;}}


function renderKeynade(p){document.title='Keynade MX — One Goods Studio';qs('#full-product').innerHTML=`<div class="keynade-intro"><div class="keynade-gallery"><figure><img id="keynade-main-photo" src="${assetUrl(keynadePhotos[0].file)}" alt="Keynade MX · ${keynadePhotos[0].label}"><figcaption id="keynade-caption">${keynadePhotos[0].label}</figcaption></figure><div class="gallery-thumbs" role="group" aria-label="商品實拍視角">${keynadePhotos.map((photo,i)=>`<button data-gallery-index="${i}" aria-label="${photo.label}" aria-pressed="${i===0}"><img src="${assetUrl(photo.file)}" alt="" loading="lazy"></button>`).join('')}</div></div><div class="keynade-summary"><span class="eyebrow">KEYNADE MX / PRESS & RELAX</span><h1>Keynade MX</h1><p class="keynade-subtitle">12 鍵機械按壓手雷</p><p>${p.detail}</p><div class="keynade-facts"><span><b>12</b>獨立按鍵</span><span><b>MX</b>機械鍵軸結構</span><span><b>1</b>金屬珠鏈隨附</span></div><p class="keynade-price">NT$499</p><span class="sale-status">尚未開賣</span><p class="detail-note">已組裝成品，包含 12 顆已安裝軸體與 1 條金屬珠鏈。</p></div></div><section class="keynade-details"><div><span class="eyebrow">THE LITTLE DETAILS</span><h2>讓每一次按壓，都有手感。</h2><p>幾何外殼上的 12 個大面板，都是可獨立按壓的機械按鍵。頂部插銷可以拔出、插回，是造型與把玩的裝飾細節。</p><p>3D 列印的層紋與金色閃點，保留在真實物件的表面。按壓聲音與手感依搭配的軸體而定。</p></div><div class="keynade-specs"><h2>規格與隨附內容</h2><dl><div><dt>品名</dt><dd>Keynade MX</dd></div><div><dt>按鍵數量</dt><dd>12 個獨立機械按鍵</dd></div><div><dt>軸體結構</dt><dd>MX-Style</dd></div><div><dt>配色</dt><dd>金色閃點，依實拍展示</dd></div><div><dt>成品配置</dt><dd>Keynade MX ×1，已組裝並安裝 12 顆軸體</dd></div><div><dt>隨附配件</dt><dd>金屬珠鏈 ×1</dd></div><div><dt>價格</dt><dd>NT$499 · 尚未開賣</dd></div></dl></div></section><section class="keynade-notes"><h2>關於這件小物</h2><p>頂部插銷為裝飾零件；小面板為固定造型件，12 個大面板可按壓。實拍中的場景物件不屬於隨附內容。</p><p>目前僅展示產品資料，尚未開賣。</p></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery-index]');if(!b)return;const photo=keynadePhotos[Number(b.dataset.galleryIndex)];if(!photo)return;qs('#keynade-main-photo').src=assetUrl(photo.file);qs('#keynade-main-photo').alt='Keynade MX · '+photo.label;qs('#keynade-caption').textContent=photo.label;document.querySelectorAll('[data-gallery-index]').forEach(button=>button.setAttribute('aria-pressed',button===b));});
